// Mock rationale: we invoke the compiled binary with a known argument\n// and compare stdout to the expected ASCII pattern.\n\nuse assert_cmd::Command;\nuse predicates::prelude::*;\n\n#[test]\nfn cli_outputs_correct_pattern() {\n    // Build the binary first (cargo test builds it automatically)\n    let mut cmd = Command::cargo_bin("nightly-cryptic-qr-generator").unwrap();\n    cmd.arg("A");\n    cmd.assert()\n        .success()\n        .stdout(predicate::str::contains(" █      █"));\n}\n
